        struct EV {
            static void SendButton(Uint32 type, int x, int y) {
                SDL_Event ev; memset(&ev, 0, sizeof(ev)); ev.type = type; ev.button.button = SDL_BUTTON_LEFT; ev.button.which = SDL_TOUCH_MOUSEID;
                ev.button.x = x; ev.button.y = y; ev.button.clicks = 1; ev.button.state = (type == SDL_MOUSEBUTTONDOWN) ? SDL_PRESSED : SDL_RELEASED;
                InputUserSDL3(ev); }
            static void Move(int x, int y, int rx, int ry) {
                SDL_Event ev; memset(&ev, 0, sizeof(ev)); ev.type = SDL_MOUSEMOTION; ev.motion.which = SDL_TOUCH_MOUSEID; ev.motion.state = SDL_BUTTON_LMASK;
                ev.motion.x = x; ev.motion.y = y; ev.motion.xrel = rx; ev.motion.yrel = ry; InputUserSDL3(ev); }
            static int& Picked() { static int e = -1; return e; }   // (una clase local no puede tener estaticos propios)
            static void Action(int id) { Picked() = id; }
            static int RowY(PopupMenu* m, int row) { const int rowH = RowHeightGS + gapGS; const int oy = m->title.empty() ? 0 : rowH;
                                                      return m->y + borderGS + oy + (row - m->scroll) * rowH + rowH / 2; }
            static void Drag(int x0, int y0, int x1, int y1) {   // en pasos, con su delta (como SDL)
                int px = x0, py = y0;
                for (int k = 1; k <= 6; k++) { const int x = x0 + (x1 - x0) * k / 6, y = y0 + (y1 - y0) * k / 6; Move(x, y, x - px, y - py); px = x; py = y; } }
        };
