          EV::Drag(x, EV::RowY(m, 1), x, EV::RowY(m, 4));
          const bool highlights = m->selectIndex == 4 && EV::Picked() == -1;
          EV::SendButton(SDL_MOUSEBUTTONUP, x, EV::RowY(m, 4));
          MD_SHOW(nothingOnRest, "apoyar el dedo sobre una opcion no la elige (solo la resalta)");
